shapes = {
    ((1,1,0),(1,0,1),(0,1,0)): ('h', 3),
    ((1,0,1),(1,0,1),(1,1,1)): ('h', 2),
    ((1,0,1),(0,1,0),(0,1,0)): ('v', 2),
    ((1,1,1),(0,1,0),(1,0,1)): ('h', 4),
    ((0,1,1),(0,1,1),(1,1,1)): ('h', 2),
}
objects = []
for c0 in (0, 4):
    for r0 in range(0, h - 2, 4):
        patch = tuple(tuple(1 if grid[r0+i][c0+j] else 0 for j in range(3)) for i in range(3))
        if any(any(row) for row in patch):
            color = next(grid[r0+i][c0+j] for i in range(3) for j in range(3) if grid[r0+i][c0+j])
            typ, length = shapes.get(patch, ('h', max(1, sum(map(sum, patch)))))
            objects.append((color, typ, length))
y = 1
for color, typ, length in objects:
    if y >= h:
        break
    if typ == 'v':
        for dy in range(length):
            if y + dy < h:
                out[y+dy][m] = color
        y += length
    else:
        start = max(0, min(7-length, m-length//2))
        for dx in range(length):
            out[y][start+dx] = color
        y += 1
